mapper.select:
select split.id, split.org_id as orgId, split.appointment_id as appointmentId, DATE_FORMAT(split.split_start_time,"%H:%i") as splitStartTime, DATE_FORMAT(split.split_end_time,"%H:%i") as splitEndTime, split.assistant_id as assistantId, split.remarks, split.inservice from appointment_split split
split.org_id = #{query.orgId}
and split.appointment_id = #{query.appointmentId}
and split.assistant_id = #{query.assistantId}
and split.inservice = #{query.inservice}
and DATE_FORMAT(split.split_start_time,'%Y-%m-%d') = DATE_FORMAT(#{query.appointDate},'%Y-%m-%d')
